"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["244"],{3524(i,e,n){n.r(e),n.d(e,{metadata:()=>t,default:()=>u,frontMatter:()=>r,contentTitle:()=>s,toc:()=>c,assets:()=>l});var t=JSON.parse('{"id":"spec/use-cases","title":"Use Cases and Novelty Analysis","description":"Based on the description examples of Section 7, we concretely examine","source":"@site/docs/spec/08-use-cases.md","sourceDirName":"spec","slug":"/spec/use-cases","permalink":"/cadl-spec/docs/spec/use-cases","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":8,"frontMatter":{"sidebar_position":8,"title":"Use Cases and Novelty Analysis"},"sidebar":"specSidebar","previous":{"title":"Domain-Specific Description Examples","permalink":"/cadl-spec/docs/spec/examples"},"next":{"title":"Research Directions and Open Challenges","permalink":"/cadl-spec/docs/spec/research"}}'),a=n(4848),o=n(8453);let r={sidebar_position:8,title:"Use Cases and Novelty Analysis"},s,l={},c=[{value:"8.1 Democratization of Institutional Design for Daily Life",id:"81-democratization-of-institutional-design-for-daily-life",level:2},{value:"Local Community\\           Describe neighborhood association rules in CADL, with AI detecting contradictions and proposing improvements. Municipal staff grasp the overall picture via visualization.             OECD deliberative citizen participation [2024] only aggregates opinions. Does not reach rule formalization. OpenStad [NL, 2024] is a participatory budgeting tool, not institutional design.   Citizen-participatory formal institutional design is an uncharted area. Via CADL&#39;s overview-level description + AI support, it becomes the first framework enabling non-expert participation in institutional design.\nAutonomy Rules",id:"local-community-----------describe-neighborhood-association-rules-in-cadl-with-ai-detecting-contradictions-and-proposing-improvements-municipal-staff-grasp-the-overall-picture-via-visualization-------------oecd-deliberative-citizen-participation-2024-only-aggregates-opinions-does-not-reach-rule-formalization-openstad-nl-2024-is-a-participatory-budgeting-tool-not-institutional-design---citizen-participatory-formal-institutional-design-is-an-uncharted-area-via-cadls-overview-level-description--ai-support-it-becomes-the-first-framework-enabling-non-expert-participation-in-institutional-designautonomy-rules",level:2},{value:"8.2 Institutional Experimentation Platform for Robotics SoS",id:"82-institutional-experimentation-platform-for-robotics-sos",level:2},{value:"Multi-Domain\\                     Institutional design for SoS with multiple delivery providers (drones, ground robots, human couriers). Describe competition and collaboration between providers with incentive models.                      Last-mile delivery research: Individual optimization dominates. Multi-provider governance structure formalization remains unaddressed.                                                                                                     Describe institutional design among heterogeneous actors in a single CADL file. Experimental verification platform for Shimoyama &amp; Matsubara [2026] performance-autonomy value space.\nDelivery Coordination",id:"multi-domain---------------------institutional-design-for-sos-with-multiple-delivery-providers-drones-ground-robots-human-couriers-describe-competition-and-collaboration-between-providers-with-incentive-models----------------------last-mile-delivery-research-individual-optimization-dominates-multi-provider-governance-structure-formalization-remains-unaddressed-----------------------------------------------------------------------------------------------------describe-institutional-design-among-heterogeneous-actors-in-a-single-cadl-file-experimental-verification-platform-for-shimoyama--matsubara-2026-performance-autonomy-value-spacedelivery-coordination",level:2},{value:"8.3 Trust Foundation for IoT Data Economy",id:"83-trust-foundation-for-iot-data-economy",level:2},{value:"Healthcare Data Sharing\\   Describe inter-hospital patient data sharing rules in CADL. Formal verification of consent management, anonymization levels, and access rights.                                     HL7 FHIR: Data exchange standard but governance rule formal verification out of scope. Smart contract research for healthcare data sharing is in early stages.                         Guarantee healthcare-specific strict privacy requirements via CADL&#39;s information flow verification. Detect consent management contradictions using deontic logic.\nGovernance",id:"healthcare-data-sharing---describe-inter-hospital-patient-data-sharing-rules-in-cadl-formal-verification-of-consent-management-anonymization-levels-and-access-rights-------------------------------------hl7-fhir-data-exchange-standard-but-governance-rule-formal-verification-out-of-scope-smart-contract-research-for-healthcare-data-sharing-is-in-early-stages-------------------------guarantee-healthcare-specific-strict-privacy-requirements-via-cadls-information-flow-verification-detect-consent-management-contradictions-using-deontic-logicgovernance",level:2},{value:"8.4 Formalization and Automation of AI Governance",id:"84-formalization-and-automation-of-ai-governance",level:2},{value:"AI-Assisted\\            Automated pipeline: Natural language \u2192 CADL conversion \u2192 formal verification \u2192 deployment. LLM generates and refines CADL descriptions in dialogue with institutional designers.   LLM-Based Symboleo Generation [2024]: Natural language to legal contract specification conversion. CURRANTE [SANER 2026]: Human-in-the-loop specification \u2192 testing \u2192 code.    Complete pipeline: NL \u2192 institutional specification \u2192 verification \u2192 code generation. While Symboleo is limited to legal contracts, CADL covers entire institutions.\nInstitutional DesignWorkflow",id:"ai-assisted------------automated-pipeline-natural-language--cadl-conversion--formal-verification--deployment-llm-generates-and-refines-cadl-descriptions-in-dialogue-with-institutional-designers---llm-based-symboleo-generation-2024-natural-language-to-legal-contract-specification-conversion-currante-saner-2026-human-in-the-loop-specification--testing--code----complete-pipeline-nl--institutional-specification--verification--code-generation-while-symboleo-is-limited-to-legal-contracts-cadl-covers-entire-institutionsinstitutional-designworkflow",level:2},{value:"8.5 Summary of Novelty",id:"85-summary-of-novelty",level:2}];function d(i){let e={br:"br",h2:"h2",hr:"hr",p:"p",strong:"strong",...(0,o.R)(),...i.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(e.p,{children:"Based on the description examples of Section 7, we concretely examine\nfeasible use cases of CADL. For each use case, we clarify the novelty\nand innovation that CADL brings through comparison with existing\ntechnologies and research."}),"\n",(0,a.jsx)(e.h2,{id:"81-democratization-of-institutional-design-for-daily-life",children:"8.1 Democratization of Institutional Design for Daily Life"}),"\n",(0,a.jsx)(e.p,{children:'The description example in household rule design (Section 7.1)\ndemonstrates the possibility of fundamentally extending the scope of\napplication of traditional formal methods. IndoorWorld by Brudy et al.\n(2025) enables LLM-driven agents to simulate household physical tasks\nand social interactions, but does not provide means to describe and\nverify household governance structure (authority, responsibility,\nincentives) itself. Furthermore, according to OECD citizen participation\nreport (2024), institutionalized deliberative citizen participation\ncases increased rapidly from 22 cases in 2020 to 41 cases in 2023, yet\nno tools exist for citizens to directly "write" governance rules.'}),"\n",(0,a.jsx)(e.hr,{}),"\n",(0,a.jsxs)(e.p,{children:[(0,a.jsx)(e.strong,{children:"Use Case"}),"               ",(0,a.jsx)(e.strong,{children:"Overview"}),"                                                                                                                                                                           ",(0,a.jsx)(e.strong,{children:"Limitations of Existing Technologies"}),"                                                                                                                                                           ",(0,a.jsx)(e.strong,{children:"CADL's Novelty"})]}),"\n",(0,a.jsx)(e.hr,{}),"\n",(0,a.jsx)(e.p,{children:"Household Chore-Sharing\\   AI analyzes chore-sharing rules written in CADL and optimizes fairness (Gini coefficient) and efficiency. AI refines design level descriptions from overview-level natural language.   Chore-sharing apps (OurHome, Tody, etc.) only support task management. Rule formalization, verification, and optimization are not possible.                                                        First-in-the-world quantitative household governance design via institutional parameters (\u03B2, \u03BB). Enables formalization of implicit rules and contradiction detection.\nOptimization"}),"\n",(0,a.jsx)(e.p,{children:"Condominium\\               Formalize management bylaws in CADL and automatically detect resident rights conflicts and obligation contradictions. Describe maintenance fund sharing rules with incentive models.   Condominium management software (condominium management cloud, etc.) supports accounting and minutes management. Bylaw formal verification is not supported.                                       Formal verifiability of legal bylaws. Symboleo [Sharifi+, 2020] leads legal contract formalization, but three-layer integrated organizational governance description is unique to CADL.\nBylaw Design"}),"\n",(0,a.jsx)(e.h2,{id:"local-community-----------describe-neighborhood-association-rules-in-cadl-with-ai-detecting-contradictions-and-proposing-improvements-municipal-staff-grasp-the-overall-picture-via-visualization-------------oecd-deliberative-citizen-participation-2024-only-aggregates-opinions-does-not-reach-rule-formalization-openstad-nl-2024-is-a-participatory-budgeting-tool-not-institutional-design---citizen-participatory-formal-institutional-design-is-an-uncharted-area-via-cadls-overview-level-description--ai-support-it-becomes-the-first-framework-enabling-non-expert-participation-in-institutional-designautonomy-rules",children:"Local Community\\           Describe neighborhood association rules in CADL, with AI detecting contradictions and proposing improvements. Municipal staff grasp the overall picture via visualization.             OECD deliberative citizen participation [2024] only aggregates opinions. Does not reach rule formalization. OpenStad [NL, 2024] is a participatory budgeting tool, not institutional design.   Citizen-participatory formal institutional design is an uncharted area. Via CADL's overview-level description + AI support, it becomes the first framework enabling non-expert participation in institutional design.\nAutonomy Rules"}),"\n",(0,a.jsx)(e.h2,{id:"82-institutional-experimentation-platform-for-robotics-sos",children:"8.2 Institutional Experimentation Platform for Robotics SoS"}),"\n",(0,a.jsx)(e.p,{children:'The robot delivery system (Section 7.2) provides an innovative\nexperimental platform that fuses MAPF research and institutional design.\nZhang et al. (IJCAI 2024) proposed Payment-CBS (PCBS) introducing VCG\nmechanisms to MAPF and realized strategy-resistant route assignment, but\nformal description of overall governance structure (who decides what,\nunder what conditions rules change) is outside the scope. CADL adds\n"institutional layer" to MAPF research, making decision structures\nabove the algorithm manipulable as experimental variables.'}),"\n",(0,a.jsx)(e.hr,{}),"\n",(0,a.jsxs)(e.p,{children:[(0,a.jsx)(e.strong,{children:"Use Case"}),"                      ",(0,a.jsx)(e.strong,{children:"Overview"}),"                                                                                                                                                                                                ",(0,a.jsx)(e.strong,{children:"Limitations of Existing Technologies"}),"                                                                                                                                                                                                   ",(0,a.jsx)(e.strong,{children:"CADL's Novelty"})]}),"\n",(0,a.jsx)(e.hr,{}),"\n",(0,a.jsxs)(e.p,{children:["Institutional Parameter\\          Systematically vary CADL institutional parameters (\u03B1, \u03B2, \u03BB) on MAPF simulator, measure impacts on throughput, fairness, and resilience. Automatically construct regime maps.                                Payment-CBS [Zhang+, IJCAI 2024]: Mechanism design for route assignment but does not address institutional design variables overall. Distributed MAPF [2020]: Only computation distribution, governance distribution not considered.   Systematic exploration of institutional parameter space and automatic regime map construction. First framework treating governance structure itself as MAPF experimental variable.\nExperimentation",(0,a.jsx)(e.br,{}),"\n","Platform"]}),"\n",(0,a.jsx)(e.p,{children:"Safety Verification of Dynamic\\   Formally verify D-SoS \u21D4 C-SoS transitions responding to changes in failure rate and latency. Model checking guarantees safety invariants during transitions (collision avoidance, order loss prevention).   Adaptive governance research [Folke+, 2021]: Theoretical framework only, no formal transition condition description. AADL/HAMR: Can generate code for architecture transitions, but not institutional transitions.                       Formal verification of institutional transitions is academically unexplored. Verifiable dynamic institutional switching via CADL's transitions block and safety_invariant specification is highly novel.\nInstitutional Transitions"}),"\n",(0,a.jsx)(e.h2,{id:"multi-domain---------------------institutional-design-for-sos-with-multiple-delivery-providers-drones-ground-robots-human-couriers-describe-competition-and-collaboration-between-providers-with-incentive-models----------------------last-mile-delivery-research-individual-optimization-dominates-multi-provider-governance-structure-formalization-remains-unaddressed-----------------------------------------------------------------------------------------------------describe-institutional-design-among-heterogeneous-actors-in-a-single-cadl-file-experimental-verification-platform-for-shimoyama--matsubara-2026-performance-autonomy-value-spacedelivery-coordination",children:"Multi-Domain\\                     Institutional design for SoS with multiple delivery providers (drones, ground robots, human couriers). Describe competition and collaboration between providers with incentive models.                      Last-mile delivery research: Individual optimization dominates. Multi-provider governance structure formalization remains unaddressed.                                                                                                     Describe institutional design among heterogeneous actors in a single CADL file. Experimental verification platform for Shimoyama & Matsubara [2026] performance-autonomy value space.\nDelivery Coordination"}),"\n",(0,a.jsx)(e.h2,{id:"83-trust-foundation-for-iot-data-economy",children:"8.3 Trust Foundation for IoT Data Economy"}),"\n",(0,a.jsx)(e.p,{children:'The IoT data sharing system (Section 7.3) supports the\nsmart-contract-ification of data sharing required by EU Data Act (2024)\nfrom upstream institutional design. IoT-Gov [Computing, 2022] and\nPolicy-Based Smart Contracts [Future Internet, 2024] focus on the\nexecution layer on blockchain, but do not address the entire lifecycle\nof institutional design, verification, and evolution. CADL integrates\nthe complete pipeline: "institutional design \u2192 formal verification \u2192\ncode generation \u2192 runtime monitoring" for data sharing.'}),"\n",(0,a.jsx)(e.hr,{}),"\n",(0,a.jsxs)(e.p,{children:[(0,a.jsx)(e.strong,{children:"Use Case"}),"               ",(0,a.jsx)(e.strong,{children:"Overview"}),"                                                                                                                                                                        ",(0,a.jsx)(e.strong,{children:"Limitations of Existing Technologies"}),"                                                                                                                                               ",(0,a.jsx)(e.strong,{children:"CADL's Novelty"})]}),"\n",(0,a.jsx)(e.hr,{}),"\n",(0,a.jsx)(e.p,{children:"Smart City\\                Describe data sharing rules for municipal, private sensors, and citizen data in CADL. Automatically detect contradictions between privacy constraints and open data requirements.   IoT-Gov [2022]: Access control on Ethereum but no formal verification of privacy constraints. vCity [BSC, 2024]: Urban digital twin but no institutional description capability.   Formal contradiction detection between privacy constraints and data publication requirements. Institutional simulation platform integrated with digital twins.\nData Coordination"}),"\n",(0,a.jsx)(e.p,{children:"Industrial Data\\           Institutionalize supply chain data sharing in manufacturing with CADL. Automatically generate Solidity/Python code from SLA contracts.                                              Symboleo2SC [Sharifi+, 2024]: Realizes legal contract to Solidity conversion. However, institutional parametrization and SLA contradiction detection are outside scope.              Verify SLA constraint satisfiability with linear programming. Simultaneous verification of combined bandwidth, latency, and privacy constraints is novel.\nMarketplace"}),"\n",(0,a.jsx)(e.h2,{id:"healthcare-data-sharing---describe-inter-hospital-patient-data-sharing-rules-in-cadl-formal-verification-of-consent-management-anonymization-levels-and-access-rights-------------------------------------hl7-fhir-data-exchange-standard-but-governance-rule-formal-verification-out-of-scope-smart-contract-research-for-healthcare-data-sharing-is-in-early-stages-------------------------guarantee-healthcare-specific-strict-privacy-requirements-via-cadls-information-flow-verification-detect-consent-management-contradictions-using-deontic-logicgovernance",children:"Healthcare Data Sharing\\   Describe inter-hospital patient data sharing rules in CADL. Formal verification of consent management, anonymization levels, and access rights.                                     HL7 FHIR: Data exchange standard but governance rule formal verification out of scope. Smart contract research for healthcare data sharing is in early stages.                         Guarantee healthcare-specific strict privacy requirements via CADL's information flow verification. Detect consent management contradictions using deontic logic.\nGovernance"}),"\n",(0,a.jsx)(e.h2,{id:"84-formalization-and-automation-of-ai-governance",children:"8.4 Formalization and Automation of AI Governance"}),"\n",(0,a.jsx)(e.p,{children:'AI integration (Section 7.4) applies CADL to the field of AI governance\nwhose social importance is rapidly increasing. As of 2026, AI governance\nhas become a core issue for enterprises as "AI risk and compliance,"\nbut formal description and automatic verification of governance policies\nremain unestablished. CADL can become the first framework to formally\ndescribe AI safety contracts, authority boundaries, and human oversight\nrequirements, and automate contradiction detection and policy code\ngeneration.'}),"\n",(0,a.jsx)(e.hr,{}),"\n",(0,a.jsxs)(e.p,{children:[(0,a.jsx)(e.strong,{children:"Use Case"}),"            ",(0,a.jsx)(e.strong,{children:"Overview"}),"                                                                                                                                                                       ",(0,a.jsx)(e.strong,{children:"Limitations of Existing Technologies"}),"                                                                                                                                           ",(0,a.jsx)(e.strong,{children:"CADL's Novelty"})]}),"\n",(0,a.jsx)(e.hr,{}),"\n",(0,a.jsx)(e.p,{children:"LLM Governance\\         Describe LLM usage rules (access control, content filters, logging obligations) in CADL. Automatically generate policy code in OPA/Rego format.                                    AI Governance 2026: Procedural and ad-hoc policy management is mainstream. No formally verifiable AI governance language exists.                                                   CADL as formal specification language for AI governance policy. AI safety contract verification via assume-guarantee semantics.\nPolicy"}),"\n",(0,a.jsx)(e.p,{children:"Autonomous System\\      Describe safety contracts for autonomous systems (autonomous vehicles, drones, etc.) in CADL. Automatically generate safe controllers via reactive synthesis (GR(1)).              Kang+ [ACM TECS, 2019]: Probabilistic assume-guarantee contracts but CPS design only. Saoud+ [Automatica, 2021]: Continuous-time contracts but institutional layer excluded.   Unified safety guarantee for institutional (governance) and control (algorithm) layers. Automatic safe controller generation via reactive synthesis from contract specifications.\nSafety Certification"}),"\n",(0,a.jsxs)(e.h2,{id:"ai-assisted------------automated-pipeline-natural-language--cadl-conversion--formal-verification--deployment-llm-generates-and-refines-cadl-descriptions-in-dialogue-with-institutional-designers---llm-based-symboleo-generation-2024-natural-language-to-legal-contract-specification-conversion-currante-saner-2026-human-in-the-loop-specification--testing--code----complete-pipeline-nl--institutional-specification--verification--code-generation-while-symboleo-is-limited-to-legal-contracts-cadl-covers-entire-institutionsinstitutional-designworkflow",children:["AI-Assisted\\            Automated pipeline: Natural language \u2192 CADL conversion \u2192 formal verification \u2192 deployment. LLM generates and refines CADL descriptions in dialogue with institutional designers.   LLM-Based Symboleo Generation [2024]: Natural language to legal contract specification conversion. CURRANTE [SANER 2026]: Human-in-the-loop specification \u2192 testing \u2192 code.    Complete pipeline: NL \u2192 institutional specification \u2192 verification \u2192 code generation. While Symboleo is limited to legal contracts, CADL covers entire institutions.\nInstitutional Design",(0,a.jsx)(e.br,{}),"\n","Workflow"]}),"\n",(0,a.jsx)(e.h2,{id:"85-summary-of-novelty",children:"8.5 Summary of Novelty"}),"\n",(0,a.jsx)(e.p,{children:"Based on the above use case analysis, we summarize CADL's novelty in\nfive key points:"}),"\n",(0,a.jsxs)(e.p,{children:[(0,a.jsx)(e.strong,{children:"ID"}),"   ",(0,a.jsx)(e.strong,{children:"Novelty"}),"                                                  ",(0,a.jsx)(e.strong,{children:"Description and Differences from Existing Research"})]}),"\n",(0,a.jsx)(e.hr,{}),"\n",(0,a.jsx)(e.p,{children:'N-1      Democratization of Institutional Design                      Overview-level description + AI support enables students, citizens, and municipal staff to participate in institutional design. Existing formal methods (Symboleo, MOISE+) are expert-limited. OECD-style citizen participation only aggregates opinions and does not reach institutional "description".\nN-2      Institutionalization of Governance as Experimental Science   Systematic manipulation of institutional parameters (\u03B1, \u03B2, \u03BB) and regime map construction establishes institutional design as experimental science. Adds governance layer to MAPF research, enabling quantitative exploration of Shimoyama & Matsubara [2026] value space.\nN-3      Formal Verification of Dynamic Institutional Transitions     Formally implements theory from adaptive governance [Folke+, 2021]. Verifiable description of transition conditions, safety invariants, and rollback is academically unexplored.\nN-4      Unified Institutional Lifecycle Management                   Manage all stages design \u2192 verification \u2192 code generation \u2192 runtime monitoring in a single language. Symboleo2SC [2024] only does code generation, IoT-Gov [2022] only handles execution layer; lifecycle integration is novel.\nN-5      Institutional Integration with Digital Twins                 Provide institutional design layer to urban digital twins like vCity [BSC, 2024]. Concept enabling not only physical simulation but "institutional simulation" is highly novel.'})]})}function u(i={}){let{wrapper:e}={...(0,o.R)(),...i.components};return e?(0,a.jsx)(e,{...i,children:(0,a.jsx)(d,{...i})}):d(i)}},8453(i,e,n){n.d(e,{R:()=>r,x:()=>s});var t=n(6540);let a={},o=t.createContext(a);function r(i){let e=t.useContext(o);return t.useMemo(function(){return"function"==typeof i?i(e):{...e,...i}},[e,i])}function s(i){let e;return e=i.disableParentContext?"function"==typeof i.components?i.components(a):i.components||a:r(i.components),t.createElement(o.Provider,{value:e},i.children)}}}]);